/**
 * The plain `Dockerfile` written next to service.json. `flisk up` does not build it: for generated
 * resources the engine builds `.autogenerated/Dockerfile.app.autogenerated`. It is a starting point
 * for building the service image outside Flisk, so its port follows the service's `port`.
 */
export declare function getDockerfileTemplate(port: number, healthCheckPath?: string): string;
export declare function getShutdownHandlerTemplate(signal: string): string;
export declare function getWorkerIndexTemplate(name: string): string;
export declare function getTestTemplate(name: string): string;
